#include "../src/game/progress_save.hpp"
#include <iostream>
int main(int argc,char**argv){if(argc!=2)return 1;try{auto p=std::filesystem::path(argv[1])/"progress.dat";for(int stage=1;stage<=4;++stage){shin::ProgressSave s;s.stages=stage;s.bonus[stage%5]=true;s.save(p);shin::ProgressSave loaded;if(!loaded.read(p)||loaded.stages!=stage||!loaded.bonus[stage%5])return 2;if(stage>1){shin::ProgressSave backup;if(!backup.read(p.string()+".bak")||backup.stages!=stage-1)return 3;}}{std::ofstream f(p,std::ios::binary|std::ios::trunc);f<<"invalid";}shin::ProgressSave fallback;fallback.load(p);if(fallback.stages!=3||!fallback.bonus[3])return 4;{shin::ProgressSave pending;pending.stages=6;pending.save(p.string()+".tmp");}shin::ProgressSave recovered;recovered.load(p);if(recovered.stages!=6)return 6;
 std::cout<<"Repeated overwrite, valid previous backup and corrupt-main recovery passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 5;}}
